 if(!items.length){const empty=document.createElement('div');empty.className='empty-state';empty.append(icon(page==='favorites'?'heart':page==='local'?'music':'radio'));const heading=document.createElement('h3');heading.textContent=t(page==='favorites'?(state.favoriteType==='radio'?'emptyFavoriteRadio':'emptyFavoriteMusic'):page==='local'?(state.selectedPlaylistId?'emptyPlaylist':'emptyLocal'):'emptyRadio');const hint=document.createElement('p');hint.textContent=t(page==='favorites'?'favoriteHint':page==='local'?(state.selectedPlaylistId?'playlistHint':'localHint'):'emptyHint');empty.append(heading,hint);container.replaceChildren(empty);return;}
 if(page==='radio'&&radioStart>=items.length)radioStart=Math.max(0,Math.floor((items.length-1)/100)*100);const start=page==='radio'?radioStart:0,indices=page==='radio'?radioData().indices:rowIndices(page==='local'&&!state.selectedPlaylistId?state.localFiles:items),fragment=document.createDocumentFragment();if(start){const earlier=document.createElement('button');earlier.className='load-more load-earlier';earlier.textContent='↑ '+Math.min(100,start);earlier.setAttribute('aria-label',t('view')+' · '+t('previous'));earlier.onclick=()=>{const height=container.scrollHeight,top=container.scrollTop,count=Math.min(100,radioStart);radioStart-=count;limit+=count;renderLists();container.scrollTop=top+container.scrollHeight-height;};fragment.append(earlier);}items.slice(start,start+limit).forEach((item,index)=>fragment.append(makeRow(item,index+start,indices)));if(items.length>start+limit){const more=document.createElement('button');more.className='load-more';more.textContent='＋ '+Math.min(100,items.length-start-limit);more.setAttribute('aria-label',t('view'));more.onclick=()=>{limit+=100;renderLists();};fragment.append(more);}container.querySelectorAll('.auto-marquee').forEach(el=>marqueeResize.unobserve(el));container.replaceChildren(fragment);container.scrollTop=scroll;highlightCurrent();
