 const items=visibleItems(),currentKey=S.key(current);let target=current,at=current?(page==='radio'&&region==='ALL'&&current.type==='radio'?Number(radioData().indices.get(currentKey)||0)-1:items.findIndex(x=>x.type===current.type&&S.key(x)===currentKey)):-1,remembered=false;
 if(page==='radio'&&at<0){target=S.radioReturnTarget(state);const memoryKey=S.key(target);at=target?(region==='ALL'?Number(radioData().indices.get(memoryKey)||0)-1:items.findIndex(x=>S.key(x)===memoryKey)):-1;remembered=true;}
 if(page==='local'&&at<0){target=state.lastLocalPlayed;at=target?items.findIndex(x=>x.type==='local'&&x.path===target.path):-1;remembered=true;}if(at<0)return;
