 function field(label,type,value,id){const wrapper=document.createElement('label');wrapper.className='field';wrapper.append(document.createTextNode(t(label)));const input=document.createElement('input');input.type=type;input.value=value||'';input.id=id;input.maxLength=type==='url'?4096:300;wrapper.append(input);form.append(wrapper);return input;}
 const name=field('name','text',original?.name,'edit-name'),url=field('url','url',original?.url,'edit-url');url.autocapitalize='off';url.autocomplete='off';url.spellcheck=false;
 const regionLabel=document.createElement('label');regionLabel.className='field';regionLabel.textContent=t('countryRegion');const select=document.createElement('select');select.id='edit-region';const unknown=document.createElement('option');unknown.value='';unknown.textContent=t('unknownCountry');select.append(unknown);for(const value of [...countryData].sort((a,b)=>countryName(a.code).localeCompare(countryName(b.code),locale))){const option=document.createElement('option');option.value=value.code;option.textContent=countryName(value.code);select.append(option);}const shortcut=region==='ALL'?'TW':S.shortcutCountry(state,region);select.value=original?stationCountry(original):shortcut==='UNKNOWN'?'':shortcut;regionLabel.append(select);form.append(regionLabel);
