function removeItem(item){if(S.isProtected(state,item)){toast(t('unfavoriteFirst'));return;}confirmSheet(t('remove'),t('removeHint',{name:item.name}),()=>{if(item.type==='radio')S.removeStation(state,item);else {state.localFiles=state.localFiles.filter(x=>x.path!==item.path);state.favorites=state.favorites.filter(x=>!(x.type==='local'&&x.path===item.path));S.prunePlaylists(state);}persist();renderLists();refreshPlayer();toast(t('removed'));},true);}
