function refreshMusicAccess(){try{const access=api.musicAccess();$('btn-all-files').hidden=!access.allFilesSupported;$('music-access-note').textContent=t(access.media?'musicAccessGranted':'musicAccessMissing')+' · '+t(access.allFiles?'allFilesGranted':'allFilesMissing');}catch{}}
window.refreshMusicAccess=refreshMusicAccess;
