async function scanMusicLibrary(){if(scanningMusic)return;scanningMusic=true;$('btn-scan-music').disabled=true;try{let access=api.musicAccess();if(!access.canRead)access=await requestMusicAccess();if(!access?.canRead)return;toast(t('scanningMusic'));const result=await api.scanMusic();if(result.denied){toast(t('musicAccessMissing'));return;}const activePath=(observed.playing||observed.preparing)?state.lastPlayed?.path||'':'';const previous=S.normalize(state);const summary=S.mergeScan(state,result.items||[],activePath);clearTimeout(persistTimer);try{api.save(state);}catch(error){state=previous;renderPage();refreshPlayer();throw error;}renderPage();refreshPlayer();const detail=t('scanSummary',{n:summary.added,r:summary.relinked,a:summary.ambiguous,d:summary.deferred})+' '+t('scanExcludedHint')+(result.truncated?' '+t('scanLimit'):'');openSheet(t('scanMusic'));const p=document.createElement('p');p.textContent=detail;$('sheet-content').append(p);sheetButton(t('confirm'),closeSheet,'primary-button');}catch{toast(t('scanFailed'));}finally{scanningMusic=false;$('btn-scan-music').disabled=false;refreshMusicAccess();}}
