function selectPlaylist(id){state.selectedPlaylistId=id;limit=100;radioStart=0;setSelecting(false);persist(true);closeSheet();renderPage();$('library-list').scrollTop=0;focusCurrentItem();}
function openPlaylists(){openSheet(t('playlists'));sheetButton((!state.selectedPlaylistId?'✓ ':'')+t('allMusic')+' · '+state.localFiles.length,()=>selectPlaylist(''));for(const group of state.playlists)sheetButton((group.id===state.selectedPlaylistId?'✓ ':'')+group.name+' · '+S.playlistItems(state,group.id).length,()=>selectPlaylist(group.id));sheetButton('＋ '+t('newPlaylist'),()=>editPlaylist());sheetButton(t('scanMusic'),()=>{closeSheet();scanMusicLibrary();});const group=state.playlists.find(x=>x.id===state.selectedPlaylistId);if(group){sheetButton(t('renamePlaylist'),()=>editPlaylist(group));sheetButton(t('deletePlaylist'),()=>confirmSheet(t('deletePlaylist'),t('playlistDeleteHint',{name:group.name}),()=>{if(state.playbackContext==='playlist'&&state.activePlaylistId===group.id){api.command('stop');stopped=true;observed={};pendingPlayKey='';}S.deletePlaylist(state,group.id);persist(true);renderPage();refreshPlayer();},true),'danger-button');}}
function editPlaylist(group=null,after=null){openSheet(t(group?'renamePlaylist':'newPlaylist'));const form=document.createElement('form'),label=document.createElement('label'),input=document.createElement('input'),error=document.createElement('p'),save=document.createElement('button');label.className='field';label.textContent=t('playlistName');input.type='text';input.id='playlist-name';input.maxLength=80;input.required=true;input.value=group?.name||'';label.append(input);error.className='form-error';error.setAttribute('role','alert');save.type='submit';save.className='primary-button';save.textContent=t('save');form.append(label,error,save);$('sheet-content').append(form);form.onsubmit=e=>{e.preventDefault();let result;if(group){if(S.renamePlaylist(state,group.id,input.value))result=group;}else result=S.createPlaylist(state,input.value);if(!result){error.textContent=t('playlistNameError');return;}persist(true);if(after)after(result);else selectPlaylist(result.id);};setTimeout(()=>input.focus(),100);}
function choosePlaylist(items){if(!items.length)return;openSheet(t('addToPlaylist'));const add=group=>{const n=S.addToPlaylist(state,group.id,items);setSelecting(false);persist(true);closeSheet();renderPage();toast(t('playlistAdded',{n}));};for(const group of state.playlists)sheetButton(group.name+' · '+S.playlistItems(state,group.id).length,()=>add(group));sheetButton('＋ '+t('newPlaylist'),()=>editPlaylist(null,add),'primary-button');}

function openSleep(){openSheet(t('sleep'));const p=document.createElement('p');p.textContent=t('sleepDescription');$('sheet-content').append(p);const grid=document.createElement('div');grid.className='sleep-grid';for(const n of [15,30,45,60,90,120,180,240]){const b=document.createElement('button');b.textContent=t('minutes',{n});b.onclick=()=>setSleep(n);grid.append(b);}$('sheet-content').append(grid);const custom=document.createElement('form');custom.className='sleep-custom';const input=document.createElement('input');input.type='number';input.min='1';input.max='240';input.placeholder=t('customMinutes');input.setAttribute('aria-label',t('customMinutes'));input.required=true;const start=document.createElement('button');start.textContent=t('start');custom.append(input,start);custom.onsubmit=e=>{e.preventDefault();if(custom.reportValidity())setSleep(Number(input.value));};$('sheet-content').append(custom);sheetButton(t('off'),()=>setSleep(0));}
function setSleep(n){if(!Number.isFinite(n)||n<0||n>240)return;api.sleep(n);observed.sleepDeadline=n?Date.now()+n*60000:0;observed.backgroundDeadline=0;refreshPlayer();closeSheet();toast(t(n?'sleepSet':'sleepCanceled',{n}));}
function help(){openSheet(t('help'));const p=document.createElement('p');p.textContent=t('helpBody')+'\n\n'+t(state.backgroundAutoOff?'backgroundRule':'backgroundRuleOff')+'\n\n'+t('permissionHint');p.style.whiteSpace='pre-line';$('sheet-content').append(p);}
function showSources(){openSheet(t('sources'));for(const provider of api.sources().providers||[]){const card=document.createElement('article');card.className='source-card';const title=document.createElement('strong');title.textContent=provider.name;const repo=document.createElement('code');repo.textContent='github.com/'+provider.repo;const note=document.createElement('p');note.textContent=provider.license+'\n'+provider.checkedRepositoryAt.slice(0,10)+(provider.attribution?'\n'+provider.attribution:'');const button=document.createElement('button');button.textContent='GitHub ↗';button.setAttribute('aria-label','GitHub '+provider.repo);button.onclick=()=>api.openSource(provider.id);card.append(title,document.createElement('br'),repo,note,button);$('sheet-content').append(card);}const attribution=document.createElement('p');attribution.className='catalog-note';attribution.textContent='Country/region names: Unicode CLDR · Unicode-3.0 · github.com/unicode-org/cldr-json';$('sheet-content').append(attribution);}
function syncCache(){const remote=api.catalog(),result=S.mergeRemote(state,remote);if(result.changed){persist(true);renderLists();refreshPlayer();}return result;}
function refreshUpdateNote(){const status=remoteStatus;$('update-indicator').textContent=status.running?'…':'↻';$('btn-update').disabled=!!status.running;$('update-note').textContent=status.running?t('updating'):status.lastSuccess?t('lastUpdated',{date:new Date(status.lastSuccess).toLocaleString(locale)})+' · '+(status.provider||'GitHub')+' · '+status.count+(status.countryCount?' · '+t('countriesCount',{n:status.countryCount}):''):status.ok===false?t('updateFailed'):t('neverUpdated');}
async function updateCatalog(){if(requestInFlight)return;requestInFlight=true;remoteStatus={...remoteStatus,running:true};refreshUpdateNote();try{remoteStatus=await api.updateCatalog();syncCache();toast(t(remoteStatus.running?'updating':remoteStatus.ok?'updated':'updateFailed',{n:remoteStatus.count||0}));}catch{toast(t('updateFailed'));}finally{requestInFlight=false;remoteStatus=api.updateStatus();refreshUpdateNote();}}
async function pickAudio(){try{const files=await api.pickAudio();let added=0;const picked=[];for(const raw of files){const file=S.item(raw,'local');if(file)picked.push(file);if(file&&!state.localFiles.some(x=>x.path===file.path)){state.localFiles.push(file);added++;}else if(file){const old=state.localFiles.find(x=>x.path===file.path);if(old)S.relinkLocal(state,old,file);}}if(state.selectedPlaylistId)S.addToPlaylist(state,state.selectedPlaylistId,picked);persist(true);renderLists();if(added)toast(t('addedMusic',{n:added}));}catch{toast(t('pickFailed'));}}
async function importBackup(){try{const raw=await api.importSettings();if(!raw)return;S.validateBackup(raw);const next=S.normalize(raw.settings||raw,catalog.stations);next.localFiles=next.localFiles.filter(x=>(x.path.startsWith('content://')||x.path.startsWith('file://')));next.favorites=next.favorites.filter(x=>x.type==='radio'||(x.path.startsWith('content://')||x.path.startsWith('file://')));if(next.lastPlayed?.type==='local')next.lastPlayed=null;state=S.mergeProtectedImport(state,next);try{AMNative.clearCarMemory();}catch{}settingsReturnView=null;state.catalogVersion=catalog.version;api.command('stop');observed={};persist(true);api.volume(state.volume);api.languageChanged();applyAppearance();applyLanguage();toast(t('imported'));}catch{toast(t('importFailed'));}}
function restoreBuiltins(){for(const raw of catalog.stations){const value=S.item(raw,'radio');if(value&&!state.stations.some(x=>x.url===value.url))state.stations.push(value);}const builtinKeys=new Set(catalog.stations.flatMap(x=>[x.id,'url:'+x.url]));state.removed=state.removed.filter(x=>!builtinKeys.has(x));persist();renderLists();toast(t('restored'));}
async function refreshMetadata(){toast(t('metadataUpdating'));$('setting-encoding').disabled=true;try{for(let i=0;i<state.localFiles.length;i+=200){const values=await api.metadata(state.localFiles.slice(i,i+200));for(const value of values){for(const field of ['localFiles','favorites','recent'])state[field]=state[field].map(x=>x.type==='local'&&x.path===value.path?{...x,...value}:x);if(state.lastPlayed?.type==='local'&&state.lastPlayed.path===value.path)state.lastPlayed={...state.lastPlayed,...value};}persist(true);}renderLists();refreshPlayer();toast(t('changed'));}catch{toast(t('pickFailed'));}finally{$('setting-encoding').disabled=false;}}
function receiveShared(){const report=api.shared();if(report.errors)toast(t('sharedFailed'));if(!report.items?.length)return;const result=S.importShared(state,report.items);if(!result.received)return;persist(true);renderPage();refreshPlayer();toast(t(result.added?'sharedReceived':'sharedAlready',{n:result.added}));if(report.play){state.selectedPlaylistId=result.playlistId;state.activePlaylistId=result.playlistId;showPage('local');playItem(result.openFirst||result.first,result.playlistId?'playlist':'local');}}

function bindUI(){
 $('setting-background-auto-off').onchange=e=>{state.backgroundAutoOff=e.target.checked;persist(true);refreshBackgroundRule();toast(t('changed'));};
 $('btn-expand-list').onclick=()=>setLibraryExpanded(!libraryExpanded);$('btn-music-access').onclick=requestMusicAccess;$('btn-scan-music').onclick=scanMusicLibrary;$('btn-all-files').onclick=()=>{try{api.openAllFiles();}catch{toast(t('musicAccessFailed'));}};
 $('btn-play').onclick=togglePlayback;$('btn-prev').onclick=()=>changeTrack(-1);$('btn-next').onclick=()=>changeTrack(1);$('btn-stop').onclick=()=>{api.command('stop');stopped=true;observed={};refreshPlayer();};$('btn-favorite').onclick=()=>toggleFavorite(state.lastPlayed);$('btn-sleep').onclick=openSleep;$('setting-sleep').onclick=openSleep;$('open-settings').onclick=toggleSettings;
 $('volume').oninput=e=>{state.volume=Number(e.target.value)/100;$('volume-label').textContent=e.target.value;api.volume(state.volume);persist();};$('seek').onchange=e=>{if(observed.duration>0)api.seek(Number(e.target.value)/1000*observed.duration/1000);};$('btn-loop').onclick=cyclePlayMode;
 document.querySelectorAll('[data-favorite-type]').forEach(b=>b.onclick=()=>switchFavoriteType(b.dataset.favoriteType));document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{showPage(b.dataset.page);if(b.dataset.page==='local'){try{const access=api.musicAccess();if(!access.canRead&&!access.asked)requestMusicAccess();}catch{}}});document.querySelectorAll('[data-region]').forEach(bindRegionButton);$('btn-add').onclick=()=>page==='local'?pickAudio():openEditor();
 document.querySelectorAll('[data-theme-choice]').forEach(b=>b.onclick=()=>{state.theme=b.dataset.themeChoice;persist();applyAppearance();toast(t('changed'));});for(const [id,key]of [['setting-motion','motion'],['setting-ticker','ticker'],['setting-auto','autoUpdate'],['setting-wifi','wifiOnly'],['setting-fallback','fallback']])$(id).onchange=e=>{state[key]=e.target.checked;persist(true);applyAppearance();};
 $('setting-language').onchange=e=>{state.language=e.target.value;persist(true);api.languageChanged();applyLanguage();toast(t('changed'));};$('setting-source').onchange=e=>{state.primarySource=e.target.value;persist(true);toast(t('changed'));};$('setting-encoding').onchange=e=>{state.textEncoding=e.target.value;persist(true);refreshMetadata();};
 $('btn-history').onclick=()=>showPage('history');$('btn-help').onclick=help;$('help-ticker').onclick=help;$('btn-sources').onclick=showSources;$('btn-update').onclick=updateCatalog;
 $('btn-export').onclick=async()=>{persist(true);try{if(await api.exportSettings(state))toast(t('exported'));}catch{toast(t('exportFailed'));}};$('btn-import').onclick=()=>confirmSheet(t('import'),t('importProtected'),importBackup);$('btn-restore').onclick=()=>confirmSheet(t('restore'),t('restoreHint'),restoreBuiltins);
 $('btn-reset').onclick=()=>{if(state.favorites.length){toast(t('protectedReset'));return;}confirmSheet(t('reset'),t('resetHint'),()=>{api.reset();settingsReturnView=null;state=S.normalize({},catalog.stations);state.catalogVersion=catalog.version;observed={};persist(true);api.volume(state.volume);applyAppearance();applyLanguage();toast(t('resetDone'));},true);};
 $('playlist-picker').onclick=openPlaylists;$('add-selected-playlist').onclick=()=>choosePlaylist(visibleItems().filter(x=>selected.has(S.selectionKey(x))));
 $('btn-select').onclick=()=>setSelecting(!selecting);$('select-all').onclick=()=>{for(const item of visibleItems())if(page==='local'||!S.isProtected(state,item))selected.add(S.selectionKey(item));renderLists();};$('delete-selected').onclick=deleteSelection;
 $('sheet-close').onclick=closeSheet;$('sheet-backdrop').onclick=e=>{if(e.target===$('sheet-backdrop'))closeSheet();};
 document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('sheet-backdrop').hidden){closeSheet();return;}if(e.key==='Tab'&&!$('sheet-backdrop').hidden){const elements=[...$('sheet').querySelectorAll('button,input,select,a')].filter(x=>!x.disabled);const first=elements[0],last=elements.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
 document.addEventListener('pointerdown',e=>{if(!state.motion)return;const button=e.target.closest('.metal-button');if(!button)return;const rect=button.getBoundingClientRect(),ripple=document.createElement('span'),size=Math.max(rect.width,rect.height);ripple.className='ripple';ripple.style.width=ripple.style.height=size+'px';ripple.style.left=e.clientX-rect.left-size/2+'px';ripple.style.top=e.clientY-rect.top-size/2+'px';button.append(ripple);setTimeout(()=>ripple.remove(),500);});
}
function poll(){
 try{const status=api.status(),previous=observed,revision=status.navigationRevision||0;const navigated=!!status.item&&((revision!==0&&revision!==(previous.navigationRevision||0))||(followNavigation&&Date.now()<followNavigationUntil&&(revision!==followNavigationFrom||S.key(status.item)!==S.key(previous.item))));if(followNavigation&&Date.now()>=followNavigationUntil)followNavigation=false;if(pendingPlayKey&&Date.now()<pendingPlayUntil&&(!status.item||S.key(status.item)!==pendingPlayKey)&&!(revision>0&&revision!==pendingPlayNavigationFrom)){receiveShared();return;}pendingPlayKey='';observed=status;if(status.lastRadioPlayed&&S.rememberRadio(state,status.lastRadioPlayed))persist();if(status.item&&['radio','local','favoriteMusic','playlist'].includes(status.playbackContext)){state.playbackContext=status.playbackContext;if(status.item.type==='radio'&&['all','country','favorites'].includes(status.radioQueueScope)){state.radioQueueScope=status.radioQueueScope;state.radioQueueCountry=status.radioQueueCountry||'';}if(status.playbackContext==='playlist')state.activePlaylistId=status.activePlaylistId||state.activePlaylistId;}if(status.item){const canonical=state.stations.find(x=>status.item.id&&x.id===status.item.id||x.url===status.item.url)||state.localFiles.find(x=>x.path===status.item.path)||status.item;const rememberedLocal=S.rememberLocal(state,canonical,status.playbackContext,status.activePlaylistId);if(rememberedLocal)persist();if(S.rememberRadio(state,canonical))persist();if(S.key(state.lastPlayed)!==S.key(canonical)||state.lastPlayed?.name!==canonical.name){state.lastPlayed={...canonical};persist();highlightCurrent();}}
  receiveShared();refreshPlayer();if(navigated){followNavigation=false;revealPlaybackItem();}if(Date.now()-lastUpdateCheck>5000){lastUpdateCheck=Date.now();const previous=remoteStatus.lastSuccess;remoteStatus=api.updateStatus();if(remoteStatus.lastSuccess!==previous)syncCache();refreshUpdateNote();}
 }catch{}
}
window.handleBack=()=>{if(!$('sheet-backdrop').hidden){closeSheet();return true;}if(selecting){setSelecting(false);return true;}if(libraryExpanded){setLibraryExpanded(false);return true;}if(page==='settings'){restoreSettingsView();return true;}if(page!=='radio'){showPage('radio');return true;}return false;};
window.addEventListener('DOMContentLoaded',()=>{
 try{systemLocale=api.locale()||navigator.language;}catch{systemLocale=navigator.language;}
 const saved=api.load();state=S.normalize(saved||{},catalog.stations);if(saved)state=S.upgrade(state,catalog).state;else state.catalogVersion=catalog.version;
 bindUI();applyAppearance();chooseLanguage();syncCache();applyLanguage();persist(true);api.volume(state.volume);remoteStatus=api.checkUpdates();refreshUpdateNote();poll();pollTimer=setInterval(poll,500);const fitObserver=new ResizeObserver(scheduleReceiverFit);fitObserver.observe($('receiver-stage'));fitObserver.observe($('receiver'));fitObserver.observe(document.querySelector('.brand'));window.addEventListener('resize',()=>{refreshLibraryExpand();scheduleReceiverFit();});const lcdObserver=new ResizeObserver(scheduleLcdAlignment);lcdObserver.observe($('elapsed'));lcdObserver.observe($('lcd-state'));document.fonts?.ready.then(()=>{lcdAlignmentKey='';scheduleReceiverFit();scheduleLcdAlignment();});scheduleReceiverFit();
});
document.addEventListener('visibilitychange',()=>{if(!state)return;persist(true);if(document.hidden){clearInterval(pollTimer);pollTimer=null;}else{try{systemLocale=api.locale();syncCache();applyLanguage();api.checkUpdates();}catch{}poll();if(!pollTimer)pollTimer=setInterval(poll,500);}});
window.addEventListener('beforeunload',()=>{clearInterval(pollTimer);if(state)persist(true);});

$('elapsed').onclick=()=>{const item=state.lastPlayed;if(item?.type!=='local'||!(observed.duration>0)){toast(t('liveNoRemaining'));return;}remainingTime=!remainingTime;refreshPlayer();};
